ALTER TABLE subcontract_progress_items DROP CONSTRAINT chk_subcontract_progress_item_values, MODIFY unit_name_snapshot VARCHAR(100) NULL, MODIFY contract_quantity DECIMAL(18,4) NULL, MODIFY unit_rate DECIMAL(18,2) NULL, MODIFY previous_quantity DECIMAL(18,4) NULL, MODIFY current_quantity DECIMAL(18,4) NULL, MODIFY cumulative_quantity DECIMAL(18,4) NULL, ADD COLUMN pricing_type_snapshot VARCHAR(20) NOT NULL DEFAULT 'quantity' AFTER description_snapshot, ADD COLUMN lump_sum_amount_snapshot DECIMAL(18,2) NULL AFTER unit_rate, ADD COLUMN previous_progress_percentage DECIMAL(7,4) NULL AFTER cumulative_quantity, ADD COLUMN current_progress_percentage DECIMAL(7,4) NULL AFTER previous_progress_percentage, ADD COLUMN cumulative_progress_percentage DECIMAL(7,4) NULL AFTER current_progress_percentage, ADD CONSTRAINT chk_subcontract_progress_item_values CHECK ((pricing_type_snapshot='quantity' AND contract_quantity IS NOT NULL AND unit_rate IS NOT NULL AND previous_quantity>=0 AND current_quantity>=0 AND cumulative_quantity>=0 AND cumulative_quantity<=contract_quantity AND lump_sum_amount_snapshot IS NULL AND previous_progress_percentage IS NULL AND current_progress_percentage IS NULL AND cumulative_progress_percentage IS NULL) OR (pricing_type_snapshot='lump_sum' AND contract_quantity IS NULL AND unit_rate IS NULL AND previous_quantity IS NULL AND current_quantity IS NULL AND cumulative_quantity IS NULL AND lump_sum_amount_snapshot>=0 AND previous_progress_percentage>=0 AND current_progress_percentage>=0 AND cumulative_progress_percentage>=0 AND cumulative_progress_percentage<=100)), ADD CONSTRAINT chk_subcontract_progress_item_pricing CHECK (pricing_type_snapshot IN('quantity','lump_sum'))
